#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll extendedGCD(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll g = extendedGCD(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, c, d;
    cin >> a >> b >> c >> d;

    ll g = std::gcd(a, c);
    if ((d - b) % g != 0) {
        cout << -1 << '\n';
        return 0;
    }

    ll mod = c / g;
    ll k = 0;

    if (mod != 1) {
        ll x, y;
        extendedGCD(a / g, mod, x, y);
        ll rhs = (d - b) / g;
        k = ((__int128)(rhs % mod + mod) % mod * (x % mod + mod)) % mod;
    }

    __int128 answer = (__int128)b + (__int128)a * k;
    __int128 lcm = (__int128)(a / g) * c;

    if (answer < d) {
        answer += ((__int128)d - answer + lcm - 1) / lcm * lcm;
    }

    string result;
    do {
        result.push_back(char('0' + answer % 10));
        answer /= 10;
    } while (answer > 0);

    reverse(result.begin(), result.end());
    cout << result << '\n';

    return 0;
}

