int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, c, d;
    cin >> a >> b >> c >> d;

    int64 g = std::gcd(a, c);
    int64 difference = d - b;

    if (difference % g != 0) {
        cout << -1 << '\n';
        return 0;
    }

    i128 modulus = c / g;
    i128 x = 0;

    if (modulus != 1) {
        i128 inverse, unused;
        extendedGcd(a / g, modulus, inverse, unused);
        inverse = (inverse % modulus + modulus) % modulus;
        x = ((i128)(difference / g) % modulus + modulus) % modulus;
        x = x * inverse % modulus;
    }

    i128 answer = (i128)b + (i128)a * x;
    i128 lcm = (i128)a / g * c;
    i128 minimum = max(b, d);

    if (answer < minimum) {
        answer += ((minimum - answer + lcm - 1) / lcm) * lcm;
    }

    printInt128(answer);
    cout << '\n';
    return 0;
}

